CREATE TABLE IF NOT EXISTS customer_migrations(version INTEGER PRIMARY KEY,applied INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS customers(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,mobile TEXT NOT NULL UNIQUE,company TEXT NOT NULL,password_hash TEXT NOT NULL,mode TEXT NOT NULL DEFAULT 'PREPAID' CHECK(mode IN ('PREPAID','POSTPAID')),balance INTEGER NOT NULL DEFAULT 0 CHECK(balance>=0),credit_limit INTEGER NOT NULL DEFAULT 0 CHECK(credit_limit>=0),outstanding INTEGER NOT NULL DEFAULT 0 CHECK(outstanding>=0),terms_days INTEGER NOT NULL DEFAULT 30,enabled INTEGER NOT NULL DEFAULT 1,state_code TEXT NOT NULL DEFAULT '',billing_gstin TEXT NOT NULL DEFAULT '',created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS customer_prices(customer_id TEXT NOT NULL REFERENCES customers(id),service TEXT NOT NULL,net INTEGER NOT NULL CHECK(net>=0),enabled INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(customer_id,service));
CREATE TABLE IF NOT EXISTS customer_settings(name TEXT PRIMARY KEY,value TEXT NOT NULL);
INSERT OR IGNORE INTO customer_settings VALUES('bonus_active','1'),('bonus_paise','3000'),('price_returns','300'),('price_challan-monthly','300'),('price_challan-yearly','3500'),('price_certificate','200'),('upi_id',''),('upi_name',''),('supplier_state','');
CREATE TABLE IF NOT EXISTS registration_attempts(id TEXT PRIMARY KEY,email TEXT NOT NULL,mobile TEXT NOT NULL,payload TEXT NOT NULL,verifier TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,sent INTEGER NOT NULL,expires INTEGER NOT NULL,used INTEGER NOT NULL DEFAULT 0,delivery TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS registration_email ON registration_attempts(email,sent);
CREATE TABLE IF NOT EXISTS customer_limits(bucket TEXT PRIMARY KEY,started INTEGER NOT NULL,count INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS customer_sessions(owner TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES customers(id),expires INTEGER NOT NULL,api_secret TEXT);
CREATE TABLE IF NOT EXISTS customer_ledger(id TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES customers(id),kind TEXT NOT NULL,amount INTEGER NOT NULL,balance_after INTEGER NOT NULL,reference TEXT NOT NULL UNIQUE,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS bonus_awards(customer_id TEXT PRIMARY KEY REFERENCES customers(id),email TEXT NOT NULL UNIQUE,mobile TEXT NOT NULL UNIQUE,amount INTEGER NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS billing_usage(id TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES customers(id),owner TEXT NOT NULL,request_key TEXT NOT NULL,service TEXT NOT NULL,mode TEXT NOT NULL,net INTEGER NOT NULL,tax INTEGER NOT NULL,gross INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN ('reserved','charged','released','review')),unit TEXT NOT NULL,created INTEGER NOT NULL,updated INTEGER NOT NULL,UNIQUE(customer_id,request_key));
CREATE TABLE IF NOT EXISTS recharge_requests(id TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES customers(id),amount INTEGER NOT NULL CHECK(amount>0),utr TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'pending',reason TEXT NOT NULL DEFAULT '',created INTEGER NOT NULL,reviewed INTEGER);
CREATE TABLE IF NOT EXISTS customer_audit(id TEXT PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,subject TEXT NOT NULL,detail TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS email_events(id TEXT PRIMARY KEY,customer_id TEXT,kind TEXT NOT NULL,status TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS password_resets(id TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES customers(id),verifier TEXT NOT NULL,expires INTEGER NOT NULL,used INTEGER NOT NULL DEFAULT 0);
INSERT OR IGNORE INTO customer_migrations VALUES(1,strftime('%s','now'));
